macro_rules! deps {
    () => {
        Shift!();
        ApproximateByteSet!();
    };
}

macro_rules! TwoWay {
    () => {
        deps!();
        # [doc = " An implementation of the TwoWay substring search algorithm."] # [doc = ""] # [doc = " This searcher supports forward and reverse search, although not"] # [doc = " simultaneously. It runs in `O(n + m)` time and `O(1)` space, where"] # [doc = " `n ~ len(needle)` and `m ~ len(haystack)`."] # [doc = ""] # [doc = " The implementation here roughly matches that which was developed by"] # [doc = " Crochemore and Perrin in their 1991 paper \"Two-way string-matching.\" The"] # [doc = " changes in this implementation are 1) the use of zero-based indices, 2) a"] # [doc = " heuristic skip table based on the last byte (borrowed from Rust's standard"] # [doc = " library) and 3) the addition of heuristics for a fast skip loop. For (3),"] # [doc = " callers can pass any kind of prefilter they want, but usually it's one"] # [doc = " based on a heuristic that uses an approximate background frequency of bytes"] # [doc = " to choose rare bytes to quickly look for candidate match positions. Note"] # [doc = " though that currently, this prefilter functionality is not exposed directly"] # [doc = " in the public API. (File an issue if you want it and provide a use case"] # [doc = " please.)"] # [doc = ""] # [doc = " The heuristic for fast skipping is automatically shut off if it's"] # [doc = " detected to be ineffective at search time. Generally, this only occurs in"] # [doc = " pathological cases. But this is generally necessary in order to preserve"] # [doc = " a `O(n + m)` time bound."] # [doc = ""] # [doc = " The code below is fairly complex and not obviously correct at all. It's"] # [doc = " likely necessary to read the Two-Way paper cited above in order to fully"] # [doc = " grok this code. The essence of it is:"] # [doc = ""] # [doc = " 1. Do something to detect a \"critical\" position in the needle."] # [doc = " 2. For the current position in the haystack, look if `needle[critical..]`"] # [doc = " matches at that position."] # [doc = " 3. If so, look if `needle[..critical]` matches."] # [doc = " 4. If a mismatch occurs, shift the search by some amount based on the"] # [doc = " critical position and a pre-computed shift."] # [doc = ""] # [doc = " This type is wrapped in the forward and reverse finders that expose"] # [doc = " consistent forward or reverse APIs."] # [derive (Clone , Copy , Debug)] struct TwoWay { # [doc = " A small bitset used as a quick prefilter (in addition to any prefilter"] # [doc = " given by the caller). Namely, a bit `i` is set if and only if `b%64==i`"] # [doc = " for any `b == needle[i]`."] # [doc = ""] # [doc = " When used as a prefilter, if the last byte at the current candidate"] # [doc = " position is NOT in this set, then we can skip that entire candidate"] # [doc = " position (the length of the needle). This is essentially the shift"] # [doc = " trick found in Boyer-Moore, but only applied to bytes that don't appear"] # [doc = " in the needle."] # [doc = ""] # [doc = " N.B. This trick was inspired by something similar in std's"] # [doc = " implementation of Two-Way."] byteset : ApproximateByteSet , # [doc = " A critical position in needle. Specifically, this position corresponds"] # [doc = " to beginning of either the minimal or maximal suffix in needle. (N.B."] # [doc = " See SuffixType below for why \"minimal\" isn't quite the correct word"] # [doc = " here.)"] # [doc = ""] # [doc = " This is the position at which every search begins. Namely, search"] # [doc = " starts by scanning text to the right of this position, and only if"] # [doc = " there's a match does the text to the left of this position get scanned."] critical_pos : usize , # [doc = " The amount we shift by in the Two-Way search algorithm. This"] # [doc = " corresponds to the \"small period\" and \"large period\" cases."] shift : Shift , }
    };
}

TwoWay!()